using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using Microsoft.Win32;
using Redshift.Services;
namespace Redshift;
public partial class MainWindow:Window {
 readonly BluestacksService bs=new(); SettingsStore settings=new(); TextBlock status=new();
 AndroidManager AndroidApi=>new(new AdbClient(settings.AdbPath));
 string? selectedDevice;
 public MainWindow(){InitializeComponent(); Loaded+=async(_,_)=>{settings=await SettingsStore.LoadAsync(); Dashboard(null,null);};}
 void Dashboard(object? s,RoutedEventArgs? e){Page("Dashboard","Your gaming environment at a glance."); Cards.Children.Clear(); foreach(var x in new[]{("BLUESTACKS",bs.Locate(settings.BlueStacksPath)!=null?"DETECTED":"NOT FOUND"),("ADB",string.IsNullOrWhiteSpace(settings.AdbPath)?"SYSTEM PATH":"CUSTOM PATH"),("PROFILES",settings.Profiles.Count.ToString()),("MODE","REDSHIFT CRIMSON")}) Cards.Children.Add(Card(x.Item1,x.Item2)); Content.Children.Clear(); Add("Launch BlueStacks",(_,_)=>Launch()); Add("Stop BlueStacks",(_,_)=>Stop()); Add("Restart BlueStacks",(_,_)=>{Stop();Launch();}); Add("Refresh diagnostics",(_,_)=>Diagnostics(null,null));}
 void Page(string t,string sub){Title.Text=t;Subtitle.Text=sub;}
 TextBlock Card(string a,string b){var t=new TextBlock{Text=a+"\n"+b,FontSize=16,Margin=new Thickness(0,0,14,14),Padding=new Thickness(18),Background=new SolidColorBrush(Color.FromRgb(32,35,48)),Width=190}; return t;}
 void Add(string text,RoutedEventHandler click){var b=new Button{Content=text};b.Click+=click;Content.Children.Add(b);}
 void Standoff(object? s,RoutedEventArgs? e){Page("Standoff 2","Apply a validated profile and restore the prior Android display values later.");Content.Children.Clear();Add("Select connected device",async(_,_)=>{var devices=await AndroidApi.ListDevicesAsync();if(devices.Count==0){status.Text="No ready ADB devices found.";return;}var dlg=new DevicePicker(devices){Owner=this};if(dlg.ShowDialog()==true){selectedDevice=dlg.SelectedDevice;status.Text=$"Selected {selectedDevice}";}});Add("Restore saved Android display",async(_,_)=>{if(selectedDevice==null){status.Text="Select a device first.";return;}if(!settings.PackageProfiles.TryGetValue("display:"+selectedDevice,out var packed)){status.Text="No saved display state. Reset defaults instead.";return;}var values=packed.Split('|');if(values.Length!=2){status.Text="Saved display backup is invalid.";return;}var api=new AdbClient(settings.AdbPath);var a=await api.ExecuteAsync($"-s {selectedDevice} shell wm size {values[0]}");var b=await api.ExecuteAsync($"-s {selectedDevice} shell wm density {values[1]}");status.Text=$"Restore size: {(a.Success?"OK":"FAILED "+a.Output)}\nRestore DPI: {(b.Success?"OK":"FAILED "+b.Output)}";});Add("Reset Android display defaults",async(_,_)=>{if(selectedDevice==null){status.Text="Select a device first.";return;}var api=new AdbClient(settings.AdbPath);var a=await api.ExecuteAsync($"-s {selectedDevice} shell wm size reset");var b=await api.ExecuteAsync($"-s {selectedDevice} shell wm density reset");status.Text=$"Reset size: {(a.Success?"OK":"FAILED "+a.Output)}\nReset DPI: {(b.Success?"OK":"FAILED "+b.Output)}";});foreach(var p in settings.Profiles) Add($"Apply {p.Name} · {p.Width}×{p.Height} · {p.Fps} FPS",async(_,_)=>{if(selectedDevice==null){status.Text="Select a device first.";return;}var validation=BluestacksService.ValidateProfile(p);if(!validation.StartsWith("supported")){status.Text=validation;return;}var api=new AdbClient(settings.AdbPath);var key="display:"+selectedDevice;if(!settings.PackageProfiles.ContainsKey(key)){var old=await new AutoProfileService(api).ReadDisplayAsync(selectedDevice);if(!old.Success){status.Text="Could not read current Android display; profile was not applied.\n"+old.Error;return;}settings.PackageProfiles[key]=$"{old.Size}|{old.Density}";await settings.SaveAsync();}var dpi=await api.ExecuteAsync($"-s {selectedDevice} shell wm density {p.Dpi}");if(!dpi.Success){status.Text="DPI change failed: "+dpi.Output;return;}var size=await api.ExecuteAsync($"-s {selectedDevice} shell wm size {p.Width}x{p.Height}");status.Text=$"{p.Name}\nDPI: {(dpi.Success?"OK":"FAILED "+dpi.Output)}\nResolution: {(size.Success?"OK":"FAILED "+size.Output)}\nScaling: {BluestacksService.ValidateScaling(settings.Scaling)}";});Add("Validate profile catalog",(_,_)=>status.Text=string.Join("\n",new ProfileCatalog().ValidateAll().Select(x=>$"{x.Profile.Name}: {x.Result}")));Content.Children.Add(status);}
 async void Performance(object? s,RoutedEventArgs? e){Page("Performance","Host and emulator metrics, plus safe configuration suggestions.");Content.Children.Clear();Add("Refresh system metrics",async(_,_)=>{var samples=await new PerformanceMonitor().SampleBlueStacksAsync();var m=GC.GetGCMemoryInfo();status.Text=$"REDSHIFT memory: {m.HeapSizeBytes/1024/1024} MB\n"+(samples.Count==0?"BlueStacks is not running.":string.Join("\n",samples.Select(x=>$"PID {x.ProcessId}: CPU {x.CpuPercent}% · RAM {x.RamMb} MB")))+"\nFPS requires a supported BlueStacks telemetry source.";});Add("Analyze and optimize safely",(_,_)=>{var report=new SmartBooster().Analyze();status.Text=$"Suggested mode: {report.Mode}\nAvailable RAM: {report.AvailableRamMb} MB\nEmulator processes: {report.EmulatorProcesses}\n"+string.Join("\n",report.Recommendations);});Content.Children.Add(status);}
 void Resolution(object? s,RoutedEventArgs? e){Page("Resolution Engine","ADB changes Android pixels; Windows scaling changes the BlueStacks window separately.");Content.Children.Clear();var modes=new ComboBox{ItemsSource=new[]{"Stretched 4:3","Stretched 16:9","Original Aspect Ratio","Custom Scaling"},SelectedItem=settings.Scaling.Mode,Height=32};var scale=new Slider{Minimum=0.5,Maximum=3,Value=Math.Clamp(settings.Scaling.Horizontal,0.5,3),TickFrequency=0.1,IsSnapToTickEnabled=false};Content.Children.Add(new TextBlock{Text="Image scaling mode"});Content.Children.Add(modes);Content.Children.Add(new TextBlock{Text="Scale factor (display only)"});Content.Children.Add(scale);Add("Save scaling mode",async(_,_)=>{settings.Scaling=settings.Scaling with{Mode=modes.SelectedItem?.ToString()??"Original Aspect Ratio",Horizontal=scale.Value,Vertical=scale.Value};await settings.SaveAsync();status.Text=BluestacksService.ValidateScaling(settings.Scaling);});Add("Find BlueStacks windows",(_,_)=>{var ws=new WindowScaler().FindBlueStacksWindows();status.Text=ws.Count==0?"No visible BlueStacks window found.":string.Join("\n",ws.Select((w,i)=>$"{i+1}. PID {w.ProcessId} · {w.Width}×{w.Height} · {w.Title}"));});Add("Apply stretched 4:3 window",(_,_)=>{var ws=new WindowScaler().FindBlueStacksWindows();if(ws.Count==0){status.Text="No visible BlueStacks window found.";return;}var w=ws[0];status.Text=new WindowScaler().ApplyStretched43(w,Math.Max(480,w.Height))?$"Window resized to 4:3 ({w.Height*4/3}×{Math.Max(480,w.Height)}). Android resolution unchanged.":"Could not resize BlueStacks window.";});Add("Select Android device",async(_,_)=>{var ds=await AndroidApi.ListDevicesAsync();if(ds.Count==0){status.Text="No ready ADB devices.";return;}var d=new DevicePicker(ds){Owner=this};if(d.ShowDialog()==true){selectedDevice=d.SelectedDevice;status.Text=$"Selected {selectedDevice}";}});Add("Reset Android display",async(_,_)=>{if(selectedDevice==null){status.Text="Select a device first.";return;}var api=new AdbClient(settings.AdbPath);var a=await api.ExecuteAsync($"-s {selectedDevice} shell wm size reset");var b=await api.ExecuteAsync($"-s {selectedDevice} shell wm density reset");status.Text=a.Output+"\n"+b.Output;});Add("Validate profiles",(_,_)=>status.Text=string.Join("\n",settings.Profiles.Select(p=>$"{p.Name}: {BluestacksService.ValidateProfile(p)}")));Content.Children.Add(status);}
 async void Android(object? s,RoutedEventArgs? e){Page("Android Manager","Connect to a ready ADB device to manage packages and files.");Content.Children.Clear();Add("Select device",async(_,_)=>{var ds=await AndroidApi.ListDevicesAsync();if(ds.Count==0){status.Text="No ready devices.";return;}var d=new DevicePicker(ds){Owner=this};if(d.ShowDialog()==true){selectedDevice=d.SelectedDevice;status.Text=$"Selected {selectedDevice}";}});Add("List packages",async(_,_)=>{var r=await AndroidApi.ListPackagesAsync();status.Text=r.Success?r.Output:"ADB: "+r.Output;});Add("Install APK",async(_,_)=>{var d=new OpenFileDialog{Filter="Android package (*.apk)|*.apk",Title="Select APK"};if(d.ShowDialog()==true){var r=await AndroidApi.InstallApkAsync(d.FileName);status.Text=r.Output;}});Add("Uninstall package…",async(_,_)=>{var prompt=new TextInputDialog("Android package name"){Owner=this};if(prompt.ShowDialog()==true){var r=await AndroidApi.UninstallAsync(prompt.Value);status.Text=r.Output;}});Add("Push file to /sdcard/Download",async(_,_)=>{var d=new OpenFileDialog{Title="Choose file to send"};if(d.ShowDialog()==true){var r=await AndroidApi.PushFileAsync(d.FileName,"/sdcard/Download/"+Path.GetFileName(d.FileName));status.Text=r.Output;}});Add("Pull file from Android…",async(_,_)=>{var prompt=new TextInputDialog("Android file path"){Owner=this};if(prompt.ShowDialog()==true){var d=new SaveFileDialog{FileName=Path.GetFileName(prompt.Value)};if(d.ShowDialog()==true){var r=await AndroidApi.PullFileAsync(prompt.Value,d.FileName);status.Text=r.Output;}}});Add("Restart Android",async(_,_)=>{var r=await AndroidApi.RestartAndroidAsync();status.Text=r.Output;});Content.Children.Add(status);}
 void Diagnostics(object? s,RoutedEventArgs? e){Page("Diagnostics","Environment checks");Content.Children.Clear();string report="";Add("Run checks",async(_,_)=>{var adb=await bs.RunAdbAsync("devices",settings.AdbPath);report=new DiagnosticsService().CreateReport(bs.Locate(settings.BlueStacksPath),adb.output,adb.ok);status.Text=report;});Add("Export report",async(_,_)=>{if(string.IsNullOrWhiteSpace(report)){status.Text="Run checks first.";return;}status.Text=$"Report exported: {await new DiagnosticsService().ExportAsync(report,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop),"REDSHIFT-Reports"))}";});Content.Children.Add(status);}
 void Settings(object? s,RoutedEventArgs? e){Page("Settings","Local REDSHIFT configuration");Content.Children.Clear();var bsPath=new TextBox{Text=settings.BlueStacksPath??"",ToolTip="Path to HD-Player.exe"};var adbPath=new TextBox{Text=settings.AdbPath??"",ToolTip="ADB executable path; blank uses PATH"};Content.Children.Add(new TextBlock{Text="BlueStacks executable"});Content.Children.Add(bsPath);Content.Children.Add(new TextBlock{Text="ADB executable"});Content.Children.Add(adbPath);Add("Save paths",async(_,_)=>{settings.BlueStacksPath=string.IsNullOrWhiteSpace(bsPath.Text)?null:bsPath.Text.Trim();settings.AdbPath=string.IsNullOrWhiteSpace(adbPath.Text)?null:adbPath.Text.Trim();await settings.SaveAsync();status.Text="Paths saved.";});Add("Export profiles",async(_,_)=>{var path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Desktop),"redshift-profiles.json");await settings.ExportProfilesAsync(path);status.Text=$"Profiles exported: {path}";});Add("Import profiles",async(_,_)=>{var d=new OpenFileDialog{Filter="REDSHIFT profiles (*.json)|*.json",Title="Import profile file"};if(d.ShowDialog()==true){var result=await settings.ImportProfilesAsync(d.FileName);status.Text=result.Message;}});Add("Create backup",async(_,_)=>{status.Text=$"Backup created: {await settings.BackupAsync()}";});Add("Restore backup",async(_,_)=>{var d=new OpenFileDialog{Filter="REDSHIFT backup (*.json)|*.json",Title="Choose settings backup"};if(d.ShowDialog()==true){await settings.RestoreAsync(d.FileName);status.Text="Backup restored. Reopen this page to refresh path fields.";}});Content.Children.Add(status);}
 void Keymapping(object? s,RoutedEventArgs? e){Page("Keymapping Studio","Edit and save a Standoff 2 key profile. BlueStacks must import/apply exported bindings separately.");Content.Children.Clear();var file=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"REDSHIFT","standoff2-keymap.json");var profile=new KeymappingProfile();var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(160)});for(int i=0;i<profile.Bindings.Count;i++){grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var action=new TextBlock{Text=profile.Bindings[i].Action,Margin=new Thickness(5),VerticalAlignment=VerticalAlignment.Center};var key=new TextBox{Text=profile.Bindings[i].Key,Margin=new Thickness(5)};Grid.SetRow(action,i);Grid.SetRow(key,i);Grid.SetColumn(key,1);grid.Children.Add(action);grid.Children.Add(key);}Content.Children.Add(grid);Add("Save edited keymap",async(_,_)=>{for(int i=0;i<profile.Bindings.Count;i++)profile.Bindings[i]=profile.Bindings[i] with{Key=((TextBox)grid.Children.Cast<UIElement>().First(x=>Grid.GetRow(x)==i&&Grid.GetColumn(x)==1)).Text.Trim()};if(!KeymappingStore.Validate(profile,out var message)){status.Text=message;return;}await new KeymappingStore().SaveAsync(profile,file);status.Text=$"{message}. Saved to {file}";});Add("Load keymap",async(_,_)=>{var p=await new KeymappingStore().LoadAsync(file);status.Text=p==null?"No keymap found.":string.Join("\n",p.Bindings.Select(x=>$"{x.Action}: {x.Key}"));});Content.Children.Add(status);}
 void Overlay(object? s,RoutedEventArgs? e){Page("Gaming Overlay","Always-on-top timer and RAM status. Set opacity and scale.");Content.Children.Clear();var opacity=new Slider{Minimum=0.2,Maximum=1,Value=settings.Overlay.Opacity};var scale=new Slider{Minimum=.6,Maximum=2,Value=settings.Overlay.Scale};Content.Children.Add(new TextBlock{Text="Opacity"});Content.Children.Add(opacity);Content.Children.Add(new TextBlock{Text="Scale"});Content.Children.Add(scale);Add("Save overlay settings",async(_,_)=>{settings.Overlay=settings.Overlay with{Opacity=opacity.Value,Scale=scale.Value};await settings.SaveAsync();status.Text=OverlayValidator.Validate(settings.Overlay);});Add("Show overlay",(_,_)=>{var cfg=settings.Overlay with{Opacity=opacity.Value,Scale=scale.Value};if(OverlayValidator.Validate(cfg)=="Overlay settings valid"){var w=new OverlayWindow();w.Configure(cfg);w.Show();status.Text="Overlay opened. Drag to move it.";}else status.Text=OverlayValidator.Validate(cfg);});Content.Children.Add(status);}
 async void Gaming(object? s,RoutedEventArgs? e){Page("Gaming Center","Find, favorite and launch installed Android packages.");Content.Children.Clear();var search=new TextBox{Height=32,Margin=new Thickness(0,0,0,12),ToolTip="Search packages"};Content.Children.Add(search);var list=new StackPanel();Content.Children.Add(list);var api=new GameLibrary(new AdbClient(settings.AdbPath));IReadOnlyList<InstalledGame> games=[];void Render(){list.Children.Clear();foreach(var g in games.Where(x=>x.PackageName.Contains(search.Text,StringComparison.OrdinalIgnoreCase)).Take(100)){var row=new StackPanel{Orientation=Orientation.Horizontal};var fav=new Button{Content=settings.FavoritePackages.Contains(g.PackageName)?"★":"☆",Width=48};fav.Click+=async(_,_)=>{if(!settings.FavoritePackages.Remove(g.PackageName))settings.FavoritePackages.Add(g.PackageName);await settings.SaveAsync();Render();};row.Children.Add(fav);var run=new Button{Content=g.PackageName,HorizontalContentAlignment=HorizontalAlignment.Left};run.Click+=async(_,_)=>{var r=await api.LaunchAsync(g.PackageName);status.Text=r.Output;};row.Children.Add(run);list.Children.Add(row);}}search.TextChanged+=(_,_)=>Render();Add("Refresh installed apps",async(_,_)=>{games=await api.DiscoverAsync();status.Text=$"Found {games.Count} packages.";Render();});Content.Children.Add(status);}
 void Instances(object? s,RoutedEventArgs? e){Page("Multi Instance","View running instances and request a supported BlueStacks launch.");Content.Children.Clear();Add("Refresh instances",(_,_)=>{var rows=new MultiInstanceManager().GetRunning();status.Text=rows.Count==0?"No HD-Player instance is running.":string.Join("\n",rows.Select(x=>$"{x.Name} · PID {x.ProcessId}"));});Add("Launch default instance",(_,_)=>Launch());Add("Launch named instance…",(_,_)=>{var d=new TextInputDialog("BlueStacks instance ID (for example Android)"){Owner=this};if(d.ShowDialog()==true){var path=bs.Locate(settings.BlueStacksPath);if(path==null){status.Text="BlueStacks executable not found.";return;}var result=new MultiInstanceManager().Start(path,d.Value);status.Text=result.message;}});Content.Children.Add(status);}
 async void Network(object? s,RoutedEventArgs? e){Page("Network Monitor","Live reachability and latency sample.");Content.Children.Clear();Add("Ping 1.1.1.1",async(_,_)=>{var n=await new NetworkMonitor().PingAsync();status.Text=n.Reachable?$"{n.Host}: {n.LatencyMs} ms":"Unreachable: "+n.Error;});Content.Children.Add(status);}
 void Launch(string args=""){var path=bs.Locate(settings.BlueStacksPath);if(path==null){status.Text="BlueStacks was not found. Set its path in Settings.";return;}try{Process.Start(new ProcessStartInfo(path,args){UseShellExecute=true});status.Text="BlueStacks launch requested.";}catch(Exception ex){status.Text=ex.Message;}}
 void Stop(){try{foreach(var p in Process.GetProcessesByName("HD-Player")) p.CloseMainWindow();status.Text="Stop requested for BlueStacks.";}catch(Exception ex){status.Text=ex.Message;}}
}
